import ScriptClass0 from './../../public/scripts/ExamplePulse.node.ts';
import ScriptClass1 from './../../public/scripts/GameMenu/MenuScript.node.ts';
import ScriptClass2 from './../../public/scripts/Gameplay/MiningScript.node.ts';
import ScriptClass3 from './../../public/scripts/Gameplay/PlayerMovementScript.node.ts';
import ScriptClass4 from './../../public/scripts/Gameplay/ShipScript.node.ts';
import ScriptClass5 from './../../public/scripts/Loading/LoadingScript.node.ts';
import ScriptClass6 from './../../public/scripts/UI/BottomHudScript.node.ts';
import ScriptClass7 from './../../public/scripts/UI/StatusHudScript.node.ts';

function createDynamicNodeModule(ScriptClass, baseName) {
  const probe = new ScriptClass();
  const nodeTypeId = typeof probe.id === 'string' && probe.id.length > 0 ? probe.id : baseName;
  const displayName = typeof probe.name === 'string' && probe.name.length > 0 ? probe.name : nodeTypeId;
  return {
    nodeTypeId,
    displayName,
    createBehavior() {
      return new ScriptClass();
    },
  };
}

const modules = [
  createDynamicNodeModule(ScriptClass0, 'ExamplePulse'),
  createDynamicNodeModule(ScriptClass1, 'GameMenu-MenuScript'),
  createDynamicNodeModule(ScriptClass2, 'Gameplay-MiningScript'),
  createDynamicNodeModule(ScriptClass3, 'Gameplay-PlayerMovementScript'),
  createDynamicNodeModule(ScriptClass4, 'Gameplay-ShipScript'),
  createDynamicNodeModule(ScriptClass5, 'Loading-LoadingScript'),
  createDynamicNodeModule(ScriptClass6, 'UI-BottomHudScript'),
  createDynamicNodeModule(ScriptClass7, 'UI-StatusHudScript')
];

export default { modules };
export { modules };
